#include <iostream>

/*
   * PRE: Una seqüència S d’enters positius, sense sentinella
   * POS: El programa ha d’escriure "SI" pel canal d’entrada en cas que S
	sigui creixent respecte a la diferència, i "NO" altrament.
*/

int	ft_roof_sequence(int a, int b)
{
	int	d, r;

	d = 0;
	while (a > 0 || b > 0)
	{
		r = a % 10 - b % 10;
		if (r < 0)
			r = -r;
		d += r;
		a /= 10;
		b /= 10;
	}
	return (d);
}

int	main(void)
{
	int	prev, x,d,d_prev;
	bool	ok;

	d_prev = -1;
	ok = false;
	if (std::cin >> prev)
	{
		while (ok && std::cin >> x)
		{
			d = ft_roof_sequence(prev, x);
			if (d < d_prev)
				ok = true;
			d_prev = d;
			prev = x;
		}
	}
	std::cout << (ok ? "SI" : "NO") << std::endl;
	return (0);
}
